// csrc/mla_preprocess/op_host/mla_preprocess.h:690
// ✅ 从 tensor shape 动态推导维度，并添加对齐检查
void Init(const torch::Tensor& wuk, const torch::Tensor& gamma1,
          const torch::Tensor& kv_cache_rope, ...) {
    // ✅ 检查 tensor 维度并动态推导 MLA 参数
    TORCH_CHECK(wuk.dim() >= 3,
        "wuk must have at least 3 dimensions, but got ", wuk.dim());
    uint32_t qkNopeHeadDim = wuk.sizes()[1];
    TORCH_CHECK(qkNopeHeadDim % 16 == 0,
        "qkNopeHeadDim must be a multiple of 16 for kernel alignment, but got ",
        qkNopeHeadDim);
    uint32_t kvLoraRank = wuk.sizes()[2];
    TORCH_CHECK(kvLoraRank > 0 && kvLoraRank % 32 == 0,
        "kvLoraRank must be a positive multiple of 32 for kernel alignment, but got ",
        kvLoraRank);

    TORCH_CHECK(gamma1.dim() >= 1,
        "gamma1 must have at least 1 dimension, but got ", gamma1.dim());
    uint32_t qLoraRank = gamma1.sizes()[0];

    TORCH_CHECK(kv_cache_rope.dim() >= 1,
        "kv_cache_rope must have at least 1 dimension, but got ",
        kv_cache_rope.dim());
    uint32_t qkRopeHeadDim = kv_cache_rope.sizes().back();
    TORCH_CHECK(qkRopeHeadDim > 0 && qkRopeHeadDim % 16 == 0,
        "qkRopeHeadDim must be a positive multiple of 16 for kernel alignment, but got ",
        qkRopeHeadDim);

    // ✅ 使用动态推导值填充 OpParam
    opParam.qkNopeHeadDim = qkNopeHeadDim;
    opParam.kvLoraRank = kvLoraRank;
    opParam.qkRopeHeadDim = qkRopeHeadDim;
    opParam.qLoraRank = qLoraRank;

    // 后续 tiling 计算使用动态值...
    tilingData->hiddenStrateRope = qkRopeHeadDim;
    tilingData->splitRmsNormSizeOne = qLoraRank;
    ...
}

